import re

def parse_val(s):
    if not s or not isinstance(s, str):
        return None
    s = s.strip()
    if s in ('', '-', '—', '(—)', 'n/a', 'N/A'):
        return None
    is_neg = s.startswith('(') and s.endswith(')')
    s = re.sub(r'[£$€%,\s]', '', s)
    s = re.sub(r'[mMkBb]$', '', s)
    s = re.sub(r'000$', '', s)
    s = re.sub(r'’000$', '', s)
    s = s.strip('()')
    if not s or s == '.':
        return None
    try:
        val = float(s)
        return -val if is_neg else val
    except ValueError:
        return None

def extract_year(s):
    if not s or not isinstance(s, str):
        return None
    m = re.search(r'\b(20\d{2})\b', s)
    return float(m.group(1)) if m else None

def get_table_node(doc, scope):
    for child in scope_nodes(doc, scope):
        if child.get('kind') == 'table':
            return child
    return None

def _get_row_labels(doc, scope):
    table_node = get_table_node(doc, scope)
    if not table_node:
        return []
    cols = table_node['table']['columns']
    first_col = cols[0]
    rows = table_rows(table_node)
    labels = []
    seen = set()
    header_kw = ['col', '(in', 'dollars', 'pounds', 'usd', 'gbp', 'eur', 'percent', '% of', '£m', '$m', 'us$m', 'm ', 'm.', 'year', 'fiscal', 'ended', 'december', 'march', 'june', 'september']
    for idx, row in rows:
        val = row.get(first_col, '').strip()
        if not val:
            continue
        if parse_val(val) is not None:
            continue
        low = val.lower()
        if any(kw in low for kw in header_kw):
            continue
        if val not in seen:
            seen.add(val)
            labels.append(val)
    return labels

def entities(doc, scope):
    labels = _get_row_labels(doc, scope)
    return [{"id": l, "description": l} for l in labels]

def recorded_end(doc, scope):
    table_node = get_table_node(doc, scope)
    if not table_node:
        return None
    cols = table_node['table']['columns']
    years = []
    for c in cols:
        y = extract_year(c)
        if y: years.append(y)
    rows = table_rows(table_node)
    for idx, row in list(rows)[:3]:
        for c in cols:
            y = extract_year(row.get(c, ''))
            if y: years.append(y)
    return max(years) if years else None

def inputs(doc, scope):
    return []

def outcomes(doc, scope):
    table_node = get_table_node(doc, scope)
    if not table_node:
        return []
    cols = table_node['table']['columns']
    first_col = cols[0]
    rows = table_rows(table_node)
    valid_ids = set(_get_row_labels(doc, scope))

    res = []
    col_years = {}
    for c in cols:
        if c == first_col: continue
        y = extract_year(c)
        if y:
            col_years[c] = y
            continue
        for idx, row in list(rows)[:3]:
            y = extract_year(row.get(c, ''))
            if y:
                col_years[c] = y
                break

    for idx, row in rows:
        entity_val = row.get(first_col, '').strip()
        if not entity_val or entity_val not in valid_ids:
            continue

        for c in cols:
            if c == first_col: continue
            cell = row.get(c, '')
            val = parse_val(cell)
            if val is None: continue

            t = col_years.get(c)
            if t is None:
                t = extract_year(cell)

            if t is not None:
                res.append({
                    "time": t,
                    "kind": "financial_metric",
                    "entities": [entity_val],
                    "value": val,
                    "src": [[table_node['node_id'], idx, [first_col, c]]]
                })
    return res

def params(doc, scope):
    return {}


