import math

def simulate(doc, scope, inputs, params, start=None, horizon=None):
    if horizon is None:
        horizon = recorded_end(doc, scope)
        if horizon is None:
            return []
    if start is None:
        start = horizon - 1.0

    # Gather historical outcomes from the document
    hist = outcomes(doc, scope)
    all_data = list(hist)

    # Incorporate exogenous inputs if provided
    if inputs:
        all_data.extend(inputs)

    # Group by entity
    entity_data = {}
    for rec in all_data:
        ent = rec['entities'][0]
        t = rec['time']
        v = rec['value']
        if ent not in entity_data:
            entity_data[ent] = []
        entity_data[ent].append((t, v))

    # Filter to entities present in inputs, if inputs are provided
    input_entities = set()
    if inputs:
        for inp in inputs:
            if 'entities' in inp and inp['entities']:
                input_entities.update(inp['entities'])
    if input_entities:
        entity_data = {k: v for k, v in entity_data.items() if k in input_entities}

    # Sort each entity's data chronologically
    for ent in entity_data:
        entity_data[ent].sort(key=lambda x: x[0])

    results = []
    step = 1.0
    current = math.floor(start) + 1.0

    while current <= horizon + 1e-6:
        for ent, data in entity_data.items():
            # Training data: records at or before start
            train = [(t, v) for t, v in data if t <= start + 0.5]
            if not train:
                # Fallback: use all available data if nothing precedes start
                train = data
            if not train:
                continue

            # Fit a simple linear model: value = slope * time + intercept
            if len(train) == 1:
                slope, intercept = 0.0, train[0][1]
            else:
                n = len(train)
                sum_t = sum(t for t, v in train)
                sum_v = sum(v for t, v in train)
                sum_tv = sum(t*v for t, v in train)
                sum_t2 = sum(t*t for t, v in train)
                denom = n * sum_t2 - sum_t * sum_t
                if abs(denom) < 1e-9:
                    # Degenerate case (e.g., all points at same time)
                    slope, intercept = 0.0, train[-1][1]
                else:
                    slope = (n * sum_tv - sum_t * sum_v) / denom
                    intercept = (sum_v - slope * sum_t) / n

            pred = slope * current + intercept
            pred = round(pred, 2)

            results.append({
                "time": current,
                "kind": "financial_metric",
                "entities": [ent],
                "value": pred,
                "src": []
            })
        current += step

    return results

