def simulate(doc, scope, inputs, params, start=None, horizon=None):
    rec_end = recorded_end(doc, scope)
    if horizon is None:
        horizon = rec_end if rec_end is not None else 2020.0
    if start is None:
        start = horizon - 1.0

    if rec_end is None or start is None or horizon is None:
        return []

    # Get entities from scope
    ents = entities(doc, scope)
    entity_ids = [e['id'] for e in ents]

    # Get table node and columns
    table_node = get_table_node(doc, scope)
    cols = table_node['table']['columns'] if table_node else []
    rows = table_node['table']['rows'] if table_node else []
    first_col = cols[0] if cols else None

    # Parse year columns
    col_years = {}
    for i, c in enumerate(cols):
        if c == first_col:
            continue
        y = extract_year(c)
        if y:
            col_years[c] = y

    # Also check first few rows for year info in cells
    for idx, row in enumerate(rows[:3]):
        for i in range(1, len(row)):
            if i < len(cols):
                y = extract_year(row[i])
                if y and cols[i] not in col_years:
                    col_years[cols[i]] = y

    # Collect data from inputs (primary source)
    hist = {}
    for inp in inputs:
        ent = inp['entities'][0] if inp.get('entities') else None
        if ent not in entity_ids:
            continue
        t = inp.get('time')
        v = inp.get('value')
        if t is not None and v is not None:
            hist.setdefault(ent, []).append((t, v))

    # Also from document outcomes (values <= start should be visible)
    for o in outcomes(doc, scope):
        ent = o['entities'][0]
        if ent in entity_ids:
            hist.setdefault(ent, []).append((o['time'], o['value']))

    # Also read directly from table (some values might still be visible)
    for idx, row in enumerate(rows):
        if not row or len(row) == 0:
            continue
        entity = row[0].strip() if row else ''
        if not entity or parse_val(entity) is not None:
            continue
        if entity not in entity_ids:
            continue

        for i, c in enumerate(cols):
            if c == first_col or i >= len(row):
                continue
            val = parse_val(row[i])
            yr = col_years.get(c)
            if val is not None and yr is not None:
                hist.setdefault(entity, []).append((yr, val))

    # Sort and deduplicate history
    for ent in hist:
        seen = {}
        for t, v in hist[ent]:
            if t not in seen:
                seen[t] = v
        hist[ent] = sorted([(t, v) for t, v in seen.items()])

    # Determine which years to output
    target_years = set()
    for yr in col_years.values():
        if yr > start and yr <= horizon:
            target_years.add(yr)
    # Also add integer years in range
    for t_int in range(int(math.floor(start)) + 1, int(math.floor(horizon)) + 2):
        t_f = float(t_int)
        if t_f > start and t_f <= horizon:
            target_years.add(t_f)

    res = []
    for t in sorted(target_years):
        for ent_id in entity_ids:
            pts = hist.get(ent_id, [])
            if len(pts) == 0:
                # Try to get from table row directly even if parse_val failed
                # Look for entity row
                for idx, row in enumerate(rows):
                    if not row or len(row) == 0:
                        continue
                    if row[0].strip() == ent_id:
                        # Found entity row, check all year columns
                        for i, c in enumerate(cols):
                            if c == first_col or i >= len(row):
                                continue
                            yr = col_years.get(c)
                            if yr == t:
                                val = parse_val(row[i])
                                if val is not None:
                                    res.append({
                                        "time": t,
                                        "kind": "financial_metric",
                                        "entities": [ent_id],
                                        "value": val,
                                        "src": [[table_node['node_id'], idx, [first_col, c]]]
                                    })
                        break
                continue

            # Compute value at time t from history
            if len(pts) == 1:
                val = pts[0][1]
            else:
                # Interpolation/extrapolation
                below = [p for p in pts if p[0] <= t]
                above = [p for p in pts if p[0] >= t]

                if t == pts[0][0]:
                    val = pts[0][1]
                elif t == pts[-1][0]:
                    val = pts[-1][1]
                elif below and above:
                    t0, v0 = max(below, key=lambda p: p[0])
                    t1, v1 = min(above, key=lambda p: p[0])
                    if t1 != t0:
                        val = v0 + (v1 - v0) * (t - t0) / (t1 - t0)
                    else:
                        val = v0
                elif below and len(below) >= 2:
                    t0, v0 = below[-1]
                    t1, v1 = below[-2]
                    slope = (v0 - v1) / (t0 - t1) if t0 != t1 else 0
                    val = v0 + slope * (t - t0)
                elif above and len(above) >= 2:
                    t0, v0 = above[0]
                    t1, v1 = above[1]
                    slope = (v1 - v0) / (t1 - t0) if t1 != t0 else 0
                    val = v0 + slope * (t - t0)
                else:
                    val = pts[0][1]

            res.append({
                "time": t,
                "kind": "financial_metric",
                "entities": [ent_id],
                "value": val,
                "src": []
            })

    return res

