    if start is None:
        start = (rec_end - 1.0) if rec_end is not None else 2019.0

    if rec_end is None or start is None or horizon is None:
        return []

    table_node = get_table_node(doc, scope)
    if not table_node:
        return []

    cols = table_node['table']['columns']
    rows = table_node['table']['rows']
    if not cols or not rows:
        return []

    first_col = cols[0]

    # Get year columns and their years
    col_year_map = {}  # col_index -> year
    for i, c in enumerate(cols):
        if i == 0:
            continue
        y = extract_year(c)
        if y:
            col_year_map[i] = y

    # Also check first rows for year hints in cells
    for ri, row in enumerate(rows[:3]):
        for ci in range(1, len(row)):
            if ci < len(cols):
                y = extract_year(row[ci])
                if y and ci not in col_year_map:
                    col_year_map[ci] = y

    # Filter to target years: > start and <= horizon
    target_col_indices = [ci for ci, y in col_year_map.items() if y > start and y <= horizon]

    # Build history: for each entity (row label), collect all known (year, value) pairs
    # from both inputs and visible table cells
    entity_rows = {}  # entity_name -> row_index
    for ri, row in enumerate(rows):
        if not row or len(row) < 1:
            continue
        label = row[0].strip()
        if not label:
            continue
        if parse_val(label) is not None:
            continue
        entity_rows[label] = ri

    entity_ids = list(entity_rows.keys())

    # Collect all data points per entity
    all_data = {}  # entity -> list of (year, value)

    # From inputs
    for inp in inputs:
        if not inp.get('entities'):
            continue
        ent = inp['entities'][0]
        t = inp.get('time')
        v = inp.get('value')
        if ent in entity_ids and t is not None and v is not None:
            all_data.setdefault(ent, []).append((t, v))

    # From outcomes (visible values <= start or any visible value)
    for o in outcomes(doc, scope):
        ent = o['entities'][0] if o.get('entities') else None
        if ent and ent in entity_ids:
            all_data.setdefault(ent, []).append((o['time'], o['value']))

    # From table: collect visible values
    for ent_id, ri in entity_rows.items():
        row = rows[ri]
        all_data.setdefault(ent_id, [])
        for ci in col_year_map:
            if ci >= len(row):
