        for t, v in pts:
            if t not in seen or abs(v) > abs(seen[t]):
                seen[t] = v
        pts = sorted(seen.items())

        # Compute growth rate if possible
        growth_rate = 0.0
        if len(pts) >= 2:
            t0, v0 = pts[0]
            t1, v1 = pts[-1]
            dt = t1 - t0
            if dt > 0 and v0 != 0:
                # Use growth rate
                growth_rate = (v1 - v0) / dt
            elif dt > 0:
                growth_rate = 0.0

        # For each target column
        for ci in target_col_indices:
            yr = col_year_map[ci]
            row = rows[entity_rows[ent_id]]

