                if pts[0][0] <= yr <= pts[-1][0]:
                    # Interpolate
                    below = [p for p in pts if p[0] <= yr]
                    above = [p for p in pts if p[0] >= yr]
                    if below and above:
                        t0, v0 = max(below, key=lambda x: x[0])
                        t1, v1 = min(above, key=lambda x: x[0])
                        if t1 != t0:
                            val = v0 + (v1 - v0) * (yr - t0) / (t1 - t0)
                        else:
                            val = v0
                    else:
                        val = pts[0][1]
                elif yr < pts[0][0]:
                    # Extrapolate backwards
                    val = pts[0][1] + growth_rate * (yr - pts[0][0])
                else:
                    # Extrapolate forwards
                    val = pts[-1][1] + growth_rate * (yr - pts[-1][0])

            if val is not None:
                src = []
                if ci < len(row) and row[ci].strip() and row[ci].strip() not in ('', '-', '—'):
                    src = [[table_node['node_id'], entity_rows[ent_id], [first_col, cols[ci]]]]
                res.append({
                    "time": yr,
                    "kind": "financial_metric",
                    "entities": [ent_id],
                    "value": round(val, 4) if val != round(val, 0) else val,
                    "src": src
                })

    return res

