    yr_start = int(start) + 1
    yr_end = int(end_time)

    for ent, records in entity_records.items():
        records.sort(key=lambda x: x['time'])
        if not records:
            continue

        # Find base value at or before start
        base_val = None
        base_time = None
        for r in records:
            if r['time'] <= start:
                base_val = r['value']
                base_time = r['time']
            else:
                break

        if base_val is None:
            continue

        # Calculate average annual change from available history
        deltas = []
        for i in range(1, len(records)):
            t1 = records[i-1]['time']
            v1 = records[i-1]['value']
            t2 = records[i]['time']
            v2 = records[i]['value']
            dt = t2 - t1
            if dt > 0:
                deltas.append((v2 - v1) / dt)
        avg_delta = sum(deltas) / len(deltas) if deltas else 0.0

        # Apply special rules for trend rates (from R-930)
        is_trend = any(kw in ent.lower() for kw in ['trend', 'health', 'medical'])

        for yr in range(yr_start, yr_end + 1):
            ty = float(yr)
            if is_trend:
                if ty <= 2024:
                    val = base_val
                elif ty <= 2029:
                    val = base_val + (4.75 - base_val) * (ty - 2024) / 5.0
                elif ty <= 2040:
                    val = 4.75 - (4.75 - 3.57) * (ty - 2029) / 11.0
                else:
                    val = 3.57
            else:
                val = base_val + avg_delta * (ty - base_time)

            results.append({
                "time": ty,
                "kind": "financial_metric",
                "entities": [ent],
                "value": val,
                "src": []
            })

    return results
